# gsplat: the package's own minimal GPU op, from
# packages/gsplat/package.yml `verify.op`. Generated by
# scripts/generate_recipes.py; edit package.yml, not this file.
import math, torch, gsplat
dev = "cuda"
means = torch.tensor([[0.0, 0.0, 3.0]], device=dev)
quats = torch.tensor([[1.0, 0.0, 0.0, 0.0]], device=dev)
scales = torch.full((1, 3), 0.5, device=dev)
opacities = torch.tensor([1.0], device=dev)
colors = torch.tensor([[1.0, 0.5, 0.25]], device=dev)
viewmats = torch.eye(4, device=dev)[None]
W = H = 32
f = W / (2 * math.tan(math.radians(30)))
Ks = torch.tensor([[[f, 0, W / 2], [0, f, H / 2], [0, 0, 1]]], device=dev)
img, alpha, meta = gsplat.rasterization(means, quats, scales, opacities,
                                        colors, viewmats, Ks, W, H)
torch.cuda.synchronize()
assert img.shape == (1, H, W, 3), img.shape
assert torch.isfinite(img).all() and torch.isfinite(alpha).all()
assert alpha.max() > 0.5, alpha.max()
assert img[..., 0].max() > 0.5, img[..., 0].max()
